package words

var labels = map[string]Text{
	"flag.aliases":               bilingual("Aliases: %s.", "別の書き方: %s。"),
	"value.profile":              bilingual("<{{profile}}>", "<{{profile}}>"),
	"value.dir":                  bilingual("<dir>", "<ディレクトリ>"),
	"value.team":                 bilingual("<{{team}}>", "<{{team-name}}>"),
	"value.purpose":              bilingual("<{{purpose}}>", "<{{purpose}}>"),
	"value.task":                 bilingual("<task>", "<依頼>"),
	"value.member":               bilingual("<{{member}}>", "<{{member}}>"),
	"value.lang":                 bilingual("en|ja", "en|ja"),
	"value.timeout":              bilingual("<ms>", "<ミリ秒>"),
	"value.port":                 bilingual("<port>", "<ポート>"),
	"rule.refusal":               bilingual("Refusal: ", "断る条件: "),
	"argument.definition":        bilingual("definition", "{{team-definition}}"),
	"argument.up-definition":     bilingual("The {{team-definition}} to {{start}}\n(left out: the lone project one)", "{{start}}する{{team-definition}}の名前\n（省くと、プロジェクトの{{team-definition}}が1つならそれ）"),
	"argument.team-or-worker":    bilingual("{{team}}|{{worker}}", "{{team}}|{{worker}}"),
	"argument.down-target":       bilingual("A {{team-name}}, or a {{worker}} of one (short or {{herdr-name}})", "{{team-name}}、または動いている{{team}}の{{worker}}（短い名前か {{herdr-name}}）"),
	"argument.team":              bilingual("{{team}}", "{{team}}"),
	"argument.status-team":       bilingual("The {{team-name}} (left out: every running {{team}})", "{{team-name}}（省くと、動いている{{team}}をすべて一覧する）"),
	"argument.member":            bilingual("{{member}}", "{{member}}"),
	"argument.refresh-member":    bilingual("The {{member}} to restart, by short {{member-name}} or {{herdr-name}}", "{{start}}し直す{{member}}（短い{{member-name}}か {{herdr-name}}）"),
	"argument.reprompt-member":   bilingual("The {{member}} to send it to, by short {{member-name}} or {{herdr-name}}", "送り直す{{member}}（短い{{member-name}}か {{herdr-name}}）"),
	"argument.apply-members":     bilingual("The {{member}}s to {{apply}}, by short {{member-name}} or {{herdr-name}}\n(left out: every {{member}} with drift)", "{{apply}}する{{member}}（短い{{member-name}}か {{herdr-name}}）\n（省くと、ずれのある{{member}}全員）"),
	"argument.focus-member":      bilingual("The {{member}} to move to, by short {{member-name}} or {{herdr-name}}", "移動先の{{member}}（短い{{member-name}}か {{herdr-name}}）"),
	"argument.nudge-member":      bilingual("The {{member}} to push, by short {{member-name}} or {{herdr-name}}", "うながす{{member}}（短い{{member-name}}か {{herdr-name}}）"),
	"argument.text":              bilingual("text", "本文"),
	"argument.nudge-text":        bilingual("What to send (left out: a short \"carry on\")", "送る本文（省くと、続けるよう短く送る）"),
	"argument.stop-member":       bilingual("The {{member}} to {{stop}}, by short {{member-name}} or {{herdr-name}}", "{{stop}}{{member}}（短い{{member-name}}か {{herdr-name}}）"),
	"argument.name":              bilingual("name", "名前"),
	"argument.tell-recipient":    bilingual("The {{member}} or {{worker}} to send to, by short name or {{herdr-name}}", "送る相手の{{member}}か{{worker}}（短い名前か {{herdr-name}}）"),
	"argument.tell-text":         bilingual("What to send. Required for a {{member}} or {{worker}}.\nThe {{human}} receives nothing and needs no text", "送る本文。{{member}}と{{worker}}へは必須。\n{{human}}へは何も送らないので要らない"),
	"argument.hire-name":         bilingual("The {{worker}}'s name (not a {{member-name}} or a {{herdr-name}} already in use)", "{{worker}}の名前（{{member-name}}とも、使用中の {{herdr-name}}とも重ならないこと）"),
	"argument.turns-team":        bilingual("The {{team-name}} (left out: the one running {{team}})", "{{team-name}}（省くと、動いている 1 つの{{team}}）"),
	"argument.team-name":         bilingual("The {{team-name}}", "{{team-name}}"),
	"argument.turn-done-member":  bilingual("The {{member}}'s or {{worker}}'s short name", "{{member}}か{{worker}}の短い名前"),
	"argument.payload":           bilingual("payload", "本文"),
	"argument.turn-done-payload": bilingual("Codex's JSON (left out: read from stdin)", "Codex の JSON（省くと標準入力から読む）"),
	"argument.show-definition":   bilingual("The {{team-definition}} to show", "表示する{{team-definition}}の名前"),
	"argument.new-definition":    bilingual("The name of the {{team-definition}} to write ([a-z][a-z0-9_-]{0,24})", "作る{{team-definition}}の名前（[a-z][a-z0-9_-]{0,24}）"),
	"up.summary":                 bilingual("Start a {{team}}", "{{team}}を{{start}}する"),
	"down.summary":               bilingual("Stop a {{team}}, or one of its {{worker}}s", "{{team}}、またはその{{worker}}を{{down}}"),
	"status.summary":             bilingual("Show how the {{member}}s and {{worker}}s are doing", "{{member}}と{{worker}}の{{status}}を見る"),
	"refresh.summary":            bilingual("Restart a {{member}}", "{{member}}を{{start}}し直す"),
	"reprompt.summary":           bilingual("Send the {{bootstrap-prompt}} again; the conversation stays", "{{bootstrap-prompt}}を送り直す。会話は残る"),
	"apply.summary":              bilingual("Apply a changed definition to a running {{team}}", "動いている{{team}}に定義の変更を{{apply}}する"),
	"focus.summary":              bilingual("Move the focus to a {{member}}'s pane", "{{member}}のペインに移動する"),
	"nudge.summary":              bilingual("Push an idle {{member}} to carry on", "{{idle}}の{{member}}に続けるよううながす"),
	"stop.summary":               bilingual("Interrupt a {{member}}'s current turn", "{{member}}の今のターンを{{stop}}"),
	"tell.summary":               bilingual("Send a message to a {{member}} or {{worker}}", "{{member}}か{{worker}}に{{tell}}（誰からかを付けられる）"),
	"hire.summary":               bilingual("Add a {{worker}}", "{{worker}}を追加する"),
	"turns.summary":              bilingual("Watch a {{team}} and ask a {{member}} that stopped without handing on", "{{team}}を見張り、渡さずに止まった{{member}}に渡し先を聞く"),
	"turn-done.summary":          bilingual("Tell hergy a {{member}}'s turn ended (the harness calls this)", "{{member}}のターンの終わりを hergy に知らせる（ハーネスが呼ぶ）"),
	"ls.summary":                 bilingual("List the {{team-definition}}s", "{{team-definition}}の一覧を見る"),
	"show.summary":               bilingual("Show the final {{team-definition}} and where each value came from", "最終的な{{team-definition}}と、その出どころを見る"),
	"new.summary":                bilingual("Write a starter {{team-definition}}", "{{team-definition}}のひな形を作る"),
	"migrate.summary":            bilingual("Migrate legacy YAML definitions to Markdown {{rule}}s", "旧形式の YAML の定義を Markdown の{{rule}}へ移す"),
	"validate.summary":           bilingual("Check the settings files", "設定ファイルを検査する"),
	"serve.summary":              bilingual("Open the web UI in a browser", "ブラウザで WebUI を開く"),
	"version.summary":            bilingual("Show the version", "バージョンを見る"),
	"cheat.summary":              bilingual("Show the {{cheatsheet}}", "{{cheatsheet}}を見る"),
	"people.steps":               bilingual("hergy cheat\n\nFirst steps\n  hergy new myteam\n  edit team.yaml\n  hergy up myteam\n\n", "hergy cheat\n\nはじめて使うとき\n  hergy new myteam\n  team.yaml を編集\n  hergy up myteam\n\n"),
	"usage.intro":                bilingual("hergy - run a {{team}} of agents on top of herdr\n\nUsage: hergy <command> [options]\n\n", "hergy - herdr の上でエージェントの{{team}}を動かす\n\n使い方: hergy <コマンド> [{{flag}}]\n\n"),
	// The two sections under the command list. A row is "label<TAB>text"; the
	// help lines its second column up with the command list's.
	"usage.options": bilingual("Common options\n--dry\tShow what would happen, and do nothing\n--as <team>\tRun the same team definition under another team name (up only)\n--team <team>\tThe team for apply, refresh, reprompt, hire, focus, nudge, stop and tell\n-C <dir>\tUse this directory as the project\n--lang en|ja\tLanguage of the command line (default en); the WebUI is Japanese\n--port <port>\tThe port hergy serve listens on (default 8787)\n", "主なオプション\n--dry\t実行せず、何をするかだけを表示する\n--as <チーム名>\t同じチーム定義を別のチーム名で動かす（up だけ）\n--team <チーム名>\tapply・refresh・reprompt・hire・focus・nudge・stop・tell の対象のチーム\n-C <ディレクトリ>\tプロジェクトの場所を指定する\n--lang en|ja\tコマンドの出力の言語（既定は en）。WebUI は日本語\n--port <ポート>\tserve が待ち受けるポート（既定 8787）\n"),
	"usage.places":  bilingual("Where team definitions live\nProject\t.hergy/teams/<definition>/team.yaml\nOutside the project\t~/.config/hergy/teams/<definition>/team.yaml\n", "チーム定義の場所\nプロジェクト\t.hergy/teams/<チーム定義>/team.yaml\nプロジェクトの外\t~/.config/hergy/teams/<チーム定義>/team.yaml\n"),
	"usage.detail":  bilingual("Details of one command: hergy <command> --help\n", "コマンドごとの説明は hergy <コマンド> --help\n"),
}

var rules = []Rule{
	{ID: "resources.rename", Commands: []string{"serve"}, Detail: true, Statement: bilingual("When renaming a {{role}} or {{profile}} with its usages selected, read every affected {{team-definition}} and prepare all reference changes before writing. If any definition cannot be read or edited, refuse the whole save without changing files and name the definitions. Write the references first and rename the {{role}} or {{profile}} last. An I/O failure during writing returns failure and lists completed and unfinished writes; earlier writes are not rolled back. Renaming a {{role}} or {{profile}} in a project changes only that project's own definitions. A {{global}} rename checks the {{global}} definitions and every registered project's definitions, respecting a project's same-named {{role}} or {{profile}}.", "{{role}}・{{profile}}の名前の変更で利用先も書き換えるときは、対象の{{team-definition}}をすべて読み、参照の編集結果を作ってから書く。読めない、または編集できない定義があれば、その定義を挙げ、ファイルを変えずに保存全体を断る。参照を先に書き、最後に{{role}}・{{profile}}の名前を変える。途中の I/O 失敗は失敗として返し、済んだ書き込みと済んでいない書き込みを示す。済んだ書き込みは戻さない。プロジェクトに置いた{{role}}・{{profile}}の名前の変更は、そのプロジェクト自身の定義だけを書き換える。{{global}}の名前の変更は、{{global}}と登録された全プロジェクトの定義を対象にし、プロジェクトの同じ名前の{{role}}・{{profile}}の{{preferred}}を保つ。")},
	{ID: "resources.definition-copy", Commands: []string{"serve"}, Statement: bilingual("A {{team-definition}} copy writes team.yaml and writes agreement.md only if the source has it. A missing agreement is left absent at the destination; an unreadable agreement refuses the copy with its {{reason}}. A copy into the {{global}} {{place}} lists the {{role-document}}s and {{profile}}s it does not hold, and writes only the ones the person chooses with the definition.", "{{team-definition}}のコピーは team.yaml と、元にある場合だけ agreement.md を書く。元に{{team-agreement}}が無ければ保存先にも作らず、読めなければ{{reason}}を示してコピーを断る。{{global}}へのコピーでは、{{global}}に無い{{role-document}}と{{profile}}を並べ、人が選んだものだけを定義と一緒に書く。")},
	{ID: "resources.delete-readers", Commands: []string{"serve"}, Statement: bilingual("The delete confirmation counts readers of a {{global}} {{role}} or {{profile}} across every registered project. Definitions that cannot be read are not included in that count.", "{{global}}の{{role}}・{{profile}}を削除する確認の人数は、登録された全プロジェクトの利用先を数える。読めない{{team-definition}}の分は人数に入らない。")},
	{ID: "resources.references-unreadable", Commands: []string{"serve"}, Statement: bilingual("The definitions cannot be updated; nothing was saved:\n%s", "次の{{team-definition}}を書き換えられないため、保存しませんでした:\n%s"), ErrorKey: "error.resource_references_unreadable", Slots: []TermID{TermTeamDefinition}},
	{ID: "resources.references-write", Commands: []string{"serve"}, Statement: bilingual("Writing failed. Completed:\n%s\nNot completed:\n%s\n%s", "書き込みに失敗しました。済んだもの:\n%s\n済んでいないもの:\n%s\n%s"), ErrorKey: "error.resource_references_write", Slots: []TermID{TermTeamDefinition, TermTeamDefinition, TermReason}},
	{ID: "web.role-inline", Commands: []string{"serve"}, Statement: bilingual("Open ロールを確認・編集 from the {{member}} attributes. This moves to the {{role}}’s {{rule}}s column beside the {{team-agreement}}. Edit the raw Markdown and save the {{role-document}} alone; saving refreshes the {{team}} {{check}}s and prompt while preserving {{team}} drafts and selection. The file {{place}} and known usages stay visible. Usage is matched to the actual file across registered projects, with the confirmed scope shown; a failed usage read disables saving. A {{global}} definition opens the same {{global}} {{role}} its displayed prompt reads. Missing or unreadable documents explain the problem and link to /{{role}}s. Rename, copy, duplicate and delete remain on /{{role}}s. The scoped link to /{{role}}s carries the {{team}} draft like the screen band does.", "{{member}}の属性かプロンプトの「{{role}}を確認・編集」で、{{team-agreement}}の横にその{{role}}の{{rule}}を開く。Markdown の全文を編集し、{{role-document}}だけを保存する。{{team-definition}}の下書きと選択を保ち、検査とプロンプトを読み直す。{{place}}と利用先を表示し、利用先を読めなければ保存できない。{{global}}の定義では、表示中のプロンプトが読む{{global}}の{{role}}を開く。実行時には同じ名前のプロジェクトの{{role}}を{{preferred}}することも示す。文書を読めないときは{{reason}}と /roles へのリンクを示す。名前の変更・コピー・複製・削除は /roles に置く。そこへ移動するリンクでも{{team}}の下書きを引き継ぐ。")},

	{ID: "dry.offline", Commands: []string{"up", "reprompt", "nudge", "stop", "tell", "hire"}, Statement: bilingual("It never reads herdr", "herdr は読まない")},
	{ID: "dry.live", Commands: []string{"down", "apply", "refresh"}, Statement: bilingual("It reads herdr's live agents and tabs", "herdr の今のエージェントとタブを読む")},

	{ID: "up.behavior", Commands: []string{"up"}, Statement: bilingual("Boot the {{team-definition}} in a new tab, with one pane and {{bootstrap-prompt}} per {{member}}. The {{team-name}} is trimmed before its shape is checked, both for --as and the screen.", "{{team-definition}}を新しいタブに{{start}}する。{{member}}ごとにペインを作り、{{bootstrap-prompt}}を渡す。"), Detail: true},
	{ID: "down.behavior", Commands: []string{"down"}, Statement: bilingual("Close the panes of the running {{team}}'s {{member}}s and of the {{worker}}s it hired. A {{team}} is what hergy made for it: the tab labelled with its name, and the panes named after it, \"<{{team}}>-<{{member}}>\". A pane whose agent ended, and one whose {{member}} never started (a boot stopped at a startup question), are closed too, so nothing hergy made is left; a pane hergy did not name is a person's own and stays. A name that is not a running {{team}} is looked for as one {{worker}} of a running {{team}} (its short name, or its {{herdr-name}} \"<{{team}}>-<{{worker}}>\"): only that {{worker}}'s pane is closed, and the {{worker}}'s own tab when that pane was the last one in it; the {{member}}s and the other {{worker}}s stay.", "{{team-name}}なら、その{{team}}の{{member}}と、hire した{{worker}}のペインを閉じる。\nエージェントが動いていない名前つきのペインも閉じる。\n動いている{{team}}に無い名前は、その{{worker}}（短い名前か {{herdr-name}}）として探し、\nその{{worker}}のペインだけを閉じる。{{worker}}のタブは、そのペインが最後の 1 枚だった\nときに閉じる。{{team-name}}にも{{worker}}名にも当たる名前は断り、両方を名指す。\n省くと、動いている{{team}}が 1 つだけのときにその{{team}}を使う。\n"), Detail: true},
	{ID: "status.behavior", Commands: []string{"status"}, Statement: bilingual("With a {{team}} name: one line per {{member}} and per {{worker}}, its live agent_status (working/idle/done/blocked), or \"not present\" when the {{member}} is not live; a {{worker}} carries \"({{worker}})\". Then a judgement line: \"waiting for a {{human}}: <names>\" when any is blocked, else \"nobody is working\" when none is working or blocked. With no {{team}} name: every running {{team}}, each with its {{team-definition-name}}, its {{member}} and {{worker}} counts, and the same judgement. It only reads herdr, and runs outside a herdr-managed pane too.", "{{member}}と{{worker}}ごとに herdr の今の{{status}}を1行ずつ出し、\n最後に、人の返事を待っている者がいるかを判定する。"), Detail: true},
	{ID: "refresh.behavior", Commands: []string{"refresh"}, Statement: bilingual("Restart each selected {{member}}. A live {{member}}: {{stop}} its process group, wait for herdr to forget the name, then {{start}} it again in the same pane and submit the {{bootstrap-prompt}}. A {{member}} that is not live: {{start}} it again in the pane hergy named after it, when that pane is still at its shell. Every {{member}} a {{refresh}} {{start}}s {{start}}s with an empty conversation. The settings are read again first, so an edited {{kind}}, args or prompt takes effect.", "選んだ{{member}}を同じペインで{{refresh}}、会話を空にする。生存していないエージェントでも、hergy が名付けたペインがシェルならそこで{{start}}する。設定を読み直すので {{kind}}・args・プロンプトの変更が入る。"), Detail: true},
	{ID: "reprompt.behavior", Commands: []string{"reprompt"}, Statement: bilingual("Re-submit the {{bootstrap-prompt}} to {{member}}s that are idle or done, keeping each one's conversation. It {{start}}s nothing.\n      Both <{{member}}> and --all is an error; neither is an error.\n      If any selected {{member}} is not idle or done, nothing is sent and the whole command errors.", "{{idle}}（idle か done）の{{member}}に{{bootstrap-prompt}}を送り直す。何も{{start}}しない。\n{{member}}か --all のどちらかを指定する。"), Detail: true},
	{ID: "apply.behavior", Commands: []string{"apply"}, Statement: bilingual("Compare the saved definition with the {{team}}s running from it and put each {{member}} right: send its prompt again when the prompt moved (the conversation stays), {{start}} a {{member}} the definition has and no agent is live for, or restart a {{member}} whose {{start}} ({{kind}} or args) changed (the conversation goes). Refused {{member}}s are left, with the {{reason}}, and the rest go on; the command answers 1 while one is left, including with --dry or --dry --json. With no {{member}} named, every {{member}} with drift is applied. The screen removes duplicate recipients, reserves every {{team}} in a selection together, and cancels the entire {{apply}} when any of those {{team}}s is stopped. A startup failure reports the {{member}}s that started, the panes left behind and the command to continue, just as a {{team}} {{start}} does. A {{worker}}'s changed {{profile}} takes effect from the next {{worker}}.", "保存した定義と動いている{{team}}を比べ、プロンプトの変更なら会話を残して{{reprompt}}、生存するエージェントが無い{{member}}は{{start}}し、{{kind}}・args の変更なら会話を消して{{start}}し直す。断った{{member}}を残して、ほかを進める。残った相手がいれば --dry と --dry --json でも終了コード1。{{member}}の指定が無ければ差分のある全員が対象。画面は宛先の重複を除き、対象{{team}}をまとめて予約する。1つでも終了されれば{{apply}}全体を{{undo}}。{{start}}の失敗では、{{start}}できた{{member}}・残ったペイン・続け方のコマンドを示す。{{worker}}の{{profile}}変更は次の{{worker}}から入る。"), Detail: true},
	{ID: "prompt.changed-preamble", Commands: []string{"reprompt", "apply"}, Detail: true, Statement: bilingual("When the {{launch-record}} shows a change, the {{bootstrap-prompt}} is headed with what changed and with the words that make it replace the previous {{bootstrap-prompt}}. A {{member}} absent from the record, or whose prompt is unchanged, receives it as it is.", "{{launch-record}}と比べて変わったことがあれば、{{bootstrap-prompt}}に変更理由と前の{{bootstrap-prompt}}を置き換える旨を前置きする。記録にない{{member}}と、プロンプトが変わっていない{{member}}には、そのまま送る。")},
	{ID: "focus.behavior", Commands: []string{"focus"}, Statement: bilingual("Move the focus to a {{member}}'s pane, by short {{member-name}} or {{herdr-name}}, so a person can answer it there. It changes nothing else.", "{{member}}のペインに移動する。人がそこで答えるため。ほかのことは何も変えない。"), Detail: true},
	{ID: "nudge.behavior", Commands: []string{"nudge"}, Statement: bilingual("Send a {{member}} a short push to carry on. The text is headed by who it is from (the {{member}} whose pane you type in, else the {{human}}); with no text, a short \"carry on\".", "{{member}}に続けるよう短く送る。"), Detail: true},
	{ID: "stop.behavior", Commands: []string{"stop"}, Statement: bilingual("Send esc to a working {{member}}, ending its current turn and keeping its conversation. An idle or done {{member}} is left alone, and the command still succeeds: there is nothing to {{stop}}. Some agents need esc twice: the first only asks them to interrupt and they keep working. hergy watches the {{member}}'s state after each esc and sends a second esc only while the {{member}} is still working, so an agent that stopped on the first is never sent a second (on some harnesses the second esc does something else). A {{member}} still working after two escs is reported as not stopped (exit 1), and {{refresh}} is named as the next step, the same step a real {{stop}} names. --dry prints what would {{stop}} and reads nothing.", "{{working}}の{{member}}に esc を送り、今のターンを終わらせる。会話は残る。\n{{idle}}（idle か done）の{{member}}には何もしないが、コマンドは成功する。\nesc を 2 回必要とするエージェントがある（1 回目の esc では止まらない）。hergy は esc を\n送るたびに{{member}}の{{status}}を見て、{{working}}のままならもう 1 回送る。1 回で止まったエージェントには\n2 回目を送らない。2 回送っても{{working}}のままなら、止まらなかったと言って失敗し（exit 1）、\nrefresh を next に出す。"), Detail: true},
	{ID: "tell.behavior", Commands: []string{"tell"}, Statement: bilingual("Send a {{member}} or {{worker}} a message headed by who it is from. Both sender and recipient accept a short name or {{herdr-name}}. --from names the sender; left out, it is the {{member}} or {{worker}} whose pane you type in, else the {{human}}. It does not {{check}} the recipient's state, so the message reaches an agent in any state. The {{tell}} is recorded for the {{team}}'s watcher ($XDG_STATE_HOME/hergy/turns/<{{team}}>.{{tell}}s/), which then knows who opened whose turn and who waits for whose answer. hergy tell {{human}} (人間, 外側, outside), typed in a {{member}}'s or {{worker}}'s pane or with --from, sends nothing and needs no text: it marks what they wrote in their pane as the person's, so the watcher does not ask who it is for when they {{stop}}; from a pane that is neither a {{member}}'s nor a {{worker}}'s it is refused.", "{{member}}と{{worker}}が、誰からかを頭に付けて本文を送る。\n相手の{{status}}は見ない。どの{{status}}のエージェントにも届く。\n{{member}}か{{worker}}のペインから打つ hergy tell {{human}} は何も送らない。\nペインに書いた文を{{human}}向けと記し、hergy turns が渡し先を聞かなくなる。"), Detail: true},
	{ID: "hire.behavior", Commands: []string{"hire"}, Statement: bilingual("Start one {{worker}} in a tab labelled {{worker}}:<{{team}}>/<name>. --purpose and --task are required. The {{worker}}'s contact guide {{tell}}s it to send its result with hergy tell to the {{member}} that hired it, then {{stop}}; questions go to that same {{member}} with hergy tell. A {{worker}} whose prompt was not received stays in its pane, and the record still names who hired it. A {{worker}} adds no teammates; ask the {{member}} that hired it when another {{worker}} is needed.", "{{member}}が、自分の{{worker}}を別タブに{{start}}して依頼を渡す。 結果と途中の質問は、{{worker}}本人が hergy tell で雇った{{member}}へ渡す。結果を渡してから止まる。 {{worker}}は仲間を増やさない。別の{{worker}}が必要なら、雇った{{member}}に頼む。"), Detail: true},
	{ID: "turns.behavior", Commands: []string{"turns"}, Statement: bilingual("Watch one running {{team}}'s turn (r-103d, r-378e). Members hand the turn on themselves with hergy tell; the watcher hands nothing on of its own. Once a second it takes the {{tell}}s hergy tell recorded and the signals the {{member}}s' harnesses wrote (hergy turn-done), and reads herdr. A turn ends when the harness says so (the signal, with the turn's last reply) or, for a {{member}} without a signal, when herdr sees the agent go from working to done or idle (then what it wrote in its pane during that turn is read); a wired {{member}}'s {{stop}} waits up to 5 seconds for the signal; a signal for a {{stop}} already acted on is dropped. Who opened the turn decides what happens when it ends. A turn the outside opened (the person's hergy tell, the {{start}} prompt, hergy's own question) rests: the reply is the person's and nothing is sent. A turn another {{member}} opened (its hergy tell, or hergy delivering an answer; a {{worker}}'s first turn: the {{member}} that hired it) that ends with a hergy tell in it was handed on by the {{member}}, and nothing more is done; one with hergy tell {{human}} in it is the person's: the turn goes to the {{human}}, those that waited wait no more, and nothing is asked. A {{tell}} that comes while the {{member}} works opens its next turn; when the turn then rests and no next turn begins within 10 seconds (a harness that folded the queued message into the running turn), that rested turn is taken as the answer and the {{member}} is asked about it. One that ends without a {{tell}} is asked about: the watcher sends the {{member}} \"who is what you wrote for?\" with the names it may answer (those waiting for it, then those the definition's turns name), {{human}} and nobody. The {{member}}'s next {{stop}} is the answer: one name, and the text that waited is sent to that {{member}} with herdr agent prompt (one that is working gets it when it {{stop}}s, as one message with everything that came meanwhile); {{human}}, nobody, no name or several leave the turn with the {{human}}, and the state says why. A {{member}} that stopped without writing a line while {{member}}s waited, one hergy could not ask (blocked, or never started), or one whose recipient never started (no working state within 5 seconds, after one retry) also leaves the turn with the {{human}}. The same {{stop}} is acted on once. blocked is not a {{stop}}. Each line in the watcher's pane says how the end was seen: [signal: claude], [herdr saw the {{stop}}], or [no signal within 5 seconds; herdr saw the {{stop}}]; a delivery decided by an answer says [as answered]. The turn's state is $XDG_STATE_HOME/hergy/turns/<team>.json (holder, who opened whose turn, the question, the box); the {{tell}}s wait in <{{team}}>.{{tell}}s/ and the signals in <{{team}}>.signals/; hergy down removes all three. Its pane shows a three-line band redrawn in {{place}}: the {{team}} and each {{member}}'s state (● working, ○ stopped, ◐ blocked), who holds the turn and from whom, who waits for whose answer; the latest handoffs with their time (→ handed, ✓ to the {{human}}, ? asked, ⟲ rested, ✗ not delivered or unclear); and what is being asked or boxed. The sentences (one per event, with how the end was seen) go to <team>.log with the time of each line; hergy turns <{{team}}> --log prints it, and hergy down leaves it. hergy up {{start}}s this in a four-row pane of the {{team}}'s tab, and it ends when the pane closes.", "tell・合図・herdr を 1 秒ごとに読む。{{hands-the-turn-to}}のは{{member}}の hergy tell。\nほかの{{member}}が開いたターンが、渡さずに終わったときだけ、本人に「誰に渡しますか」と聞く。\n答えどおりに届ける。{{human}}・誰にも・決まらない答えなら、ターンは{{human}}へ。\n{{human}}が開いたターンの終わりには何もしない。hergy up が{{team}}のタブの 4 行のペインで{{start}}する。\nペインには 3 行の帯（{{status}}・持ち主・待ち／時刻付きの直近の受け渡し／いま聞いていること）を描き、\n文のログは turns/<{{team}}>.log へ（--log で読む）。"), Detail: true},
	{ID: "turn-done.behavior", Commands: []string{"turn-done"}, Statement: bilingual("What a {{member}}'s harness calls when its turn ends (r-378e); a person does not type it. hergy up and hergy hire wire it into each {{start}} without writing into the person's own configuration: Claude Code gets --settings with a Stop hook (the person's hooks keep running), Codex gets -c notify=[hergy turn-done ...] (the person's own notify from ~/.codex/config.toml is called afterwards with the same JSON), and a --standalone opencode gets hergy's plugin directory ($XDG_STATE_HOME/hergy/opencode/hergy-turns) added to the plugins of OPENCODE_CONFIG_CONTENT (the {{profile}}'s own inline config is kept; the person's ~/.config/opencode is read as before, which OPENCODE_CONFIG_DIR would replace), with HERGY_BIN, HERGY_TEAM and HERGY_MEMBER in the pane's environment. A {{profile}} that passes --settings or notify itself, whose OPENCODE_CONFIG_CONTENT is not JSON, or that runs opencode without --standalone gets no signal, and hergy up says so; its {{stop}}s are seen through herdr. The payload is Codex's one JSON argument (last-assistant-message) or, on stdin, Claude Code's Stop hook JSON (last_assistant_message) or the plugin's {\"source\":\"opencode\",\"last_assistant_message\":...}. The signal is written for hergy turns to take.", "hergy up が{{member}}のハーネスに差し込む呼び出し。Claude Code の Stop hook、Codex の notify、\nopencode のプラグインが、ターンの終わりに最後の返答を添えて呼ぶ（Codex は引数の JSON、\nほかは標準入力）。hergy は合図を書き、{{team}}の見張り（hergy turns）がそれを読んで渡す。\n人が打つコマンドではない。"), Detail: true},
	{ID: "ls.behavior", Commands: []string{"ls"}, Statement: bilingual("List the visible {{team-definition}}s and the running {{team-name}}s each one booted.", "見える{{team-definition}}と、そこから動いている{{team-name}}を一覧する。"), Detail: true},
	{ID: "show.behavior", Commands: []string{"show"}, Statement: bilingual("Print the effective {{team-definition}} and where each value and document came from.", "最終的な{{team-definition}}と、各値と文書の出どころを表示する。"), Detail: true},
	{ID: "new.behavior", Commands: []string{"new"}, Statement: bilingual("The starter {{member}}s are lead and builder. Write team.yaml and agreement.md.\nThe {{member}}s' {{role}}s and {{profile}}s are the ones either {{place}} already holds:\nhergy writes no {{role-document}} and no {{profile}} the person did not choose.\nWhile neither {{place}} holds a {{role-document}}, it writes the starter {{role}}s\nlead and builder into {{role}}s/; while neither defines a {{profile}}, it writes\nclaude-default into profiles.yaml. Otherwise it names the {{role}}s and\n{{profile}}s to write in team.yaml, and the next step is hergy validate.\nAn existing {{team}} is never overwritten. It writes into the project's .hergy/\ninside a git repository, and into ~/.config/hergy/ outside one.\nIf the {{global}} config.yaml (version and lang) is missing, it is written too.", "ひな形の{{member}}は lead と builder。team.yaml・agreement.md を書き出す。{{member}}の{{role}}と{{profile}}は、\nプロジェクトか{{global}}のどちらかに今あるものから選ぶ。\n人が選んでいない{{role-document}}と{{profile}}は書かない。\nどちらにも{{role-document}}が 1 つも無いときだけ、ひな形の{{role}} lead・builder を\nroles/ に書く。{{profile}}も、どちらにも 1 つも無いときだけ claude-default を\nprofiles.yaml に書く。あるときは、team.yaml に書く{{role}}と{{profile}}を名指し、\n次の一手を hergy validate にする。\n既にある{{team-definition}}は上書きしない。\n書く先は、git の中ならプロジェクトの .hergy/、外なら ~/.config/hergy/。\n{{global}}の config.yaml（version と lang）は、無いときだけ作る。"), Detail: true},
	{ID: "migrate.behavior", Commands: []string{"migrate"}, Statement: bilingual("Inspect all legacy {{role}} and {{team}} YAML files in the project before writing. --global selects {{global}} settings, --dry only prints the plan. Keep adjacent .yaml.bak originals; refuse conflicting destinations. See CHANGELOG for recovery.", "プロジェクトの旧形式の{{role}}・{{team}} YAML を全件検査してから変換する。--global は{{global}}を選び、--dry は計画だけを表示する。元のバイト列を隣の .yaml.bak に残す。変換先の衝突とシンボリックリンクは断り、直すファイルを示す。復旧方法は CHANGELOG を参照する。"), Detail: true},
	{ID: "validate.behavior", Commands: []string{"validate"}, Statement: bilingual("Check the {{global}} config.yaml, every profiles.yaml, and every {{team-definition}}. Exit 1 if any is broken. It prints the size of each {{role-document}} and {{team-definition}}, each checked once. [[rules.budget]]", "{{global}}の config.yaml、すべての profiles.yaml と{{team-definition}}を検査する。壊れたものがあれば終了コード1。{{role-document}}と{{team-definition}}を1回ずつ検査し、文字数を表示する。[[rules.budget]]"), Detail: true},
	{ID: "serve.behavior", Commands: []string{"serve"}, Statement: bilingual("Serve the screens over HTTP on 127.0.0.1, print the URL and open it in this machine's default browser, in the foreground, until Ctrl-C. --port picks the port (default 8787; 0 lets the operating system pick a free one); --no-open prints the URL and opens nothing. A browser that cannot be opened is one line on stderr and serve goes on, with the URL to open by hand. It reads the settings the way the commands do, and it changes nothing but the two profiles.yaml files (a {{profile}}'s name, {{kind}}, args and env, and the {{profile}} each {{member}} and {{worker}} runs), a {{role-document}}, a {{team-definition}}'s team.yaml and agreement.md, and the projects: list of the {{global}} config.yaml. It is the {{headquarters}}: it shows the projects config.yaml lists (or, without that key, the project it was started in and the {{global}} settings), their {{team}}s, {{role}}s and {{profile}}s with the project each belongs to, the running {{team}}s and workspaces, and it {{start}}s and {{stop}}s a listed project's {{team}} with the same result as hergy up and hergy down. A {{stop}} waits for name release with the same 30000 ms deadline and reports any timeout in its result; if serve runs in a {{team}} pane, that pane stays open on timeout. A {{start}} runs in a workspace a person picks and reports its progress and a startup question at /api/hq/launches/<id>.", "127.0.0.1 で画面を配り、URL を表示し、既定のブラウザで開く。Ctrl-C まで前景で動く。--no-open はブラウザを開かない。--port は既定8787、0なら空きポートをOSが選ぶ。ブラウザを開けなくても、標準エラーに知らせて配信を続ける。終了時は処理中のリクエストを待つ。画面はCLIと同じ設定ファイルを読み書きする。"), Detail: true},
	{ID: "version.behavior", Commands: []string{"version"}, Statement: bilingual("Print the commit and time of this hergy. It takes no other {{flag}}s.", "この hergy のコミットとビルド時刻を表示する。ほかの{{flag}}は受け取らない。"), Detail: true},
	{ID: "cheat.behavior", Commands: []string{"cheat"}, Statement: bilingual("Print a {{cheatsheet}}. --ai prints this text. It reads only config.yaml, for the language, and prints even when that file is broken.", "短い{{cheatsheet}}を表示する。{{team-definition}}などの設定は読まず、壊れていても表示する。"), Detail: true},
	{ID: "prompt.receipt", Commands: []string{"up", "refresh", "reprompt", "apply", "hire"}, Statement: bilingual("\"Sent\" means herdr observed working within five seconds. Retry the identical prompt once on any sending error. If the final answer is agent_prompt_stalled, timeout or agent_blocked, name the recipient and pane, show how to send again, continue with the remaining recipients, and finish with failure listing the missing receipts. Other sending or startup failures {{stop}} the operation immediately. Only confirmed recipients get success lines.", "受け取りは herdr が5秒以内に working を確認すること。送信の失敗時は同じ{{bootstrap-prompt}}を1回だけ送り直す。最後の結果が agent_prompt_stalled・timeout・agent_blocked なら、相手・ペイン・送り直すコマンドを示し、残りの相手を処理してから、届かなかった相手を並べて失敗で終わる。ほかの送信の失敗と{{start}}の失敗はその場で止まる。受信を確認した相手だけに成功を表示する。"), Detail: true},
	{ID: "startup.question", Commands: []string{"up", "refresh", "apply", "hire"}, Statement: bilingual("If the agent asks a question while it {{start}}s (whether to trust this folder, for example), hergy names the {{member}}, the tab and the pane, waits for the answer with no limit, then sends the {{bootstrap-prompt}}, confirms receipt and goes on; a second question in a row prints nothing more. Ctrl-C {{stop}}s the wait, and the line it ends with names the way on. hergy answers nothing itself and moves no focus.", "{{start}}中にエージェントが質問したら、{{member}}・タブ・ペインを示し、{{human}}の返答を時間制限なく待つ。その後に{{bootstrap-prompt}}を送り、受信を確認する。続けて質問しても表示は増えない。Ctrl-C で待ちを{{undo}}と続け方を表示する。hergy は質問に答えず、フォーカスを移さない。"), Detail: true},
	{ID: "refresh.no-pane", Commands: []string{"refresh"}, Statement: bilingual("%s has no pane; {{refresh}} does not add a {{member}} to a running {{team}}.", "%s のペインが無い。refresh で動いている{{team}}に{{member}}を追加することはできない。"), Detail: true, Recovery: bilingual("Use hergy apply to add it.", "追加するには hergy apply を使う。"), ErrorKey: "refresh.use_apply", Slots: []TermID{"member"}},
	{ID: "refresh.own-pane", Commands: []string{"refresh"}, Statement: bilingual("%s runs in your own pane; a {{member}} cannot {{refresh}} itself. Run it from another pane, or as the {{human}}", "%s はこのペインで動いています。自分自身は{{start}}し直せないので、別のペインから実行するか、{{human}}が実行してください"), Detail: true, ErrorKey: "error.refresh_self", Slots: []TermID{"member"}},
	{ID: "refresh.busy-pane", Commands: []string{"refresh"}, Statement: bilingual("%s: the pane named after it is running something else (pane %s); run `hergy down` then `hergy up`", "%s のペイン（%s）では別のものが動いています。hergy down のあと hergy up し直してください"), Detail: true, ErrorKey: "error.refresh_pane_busy", Slots: []TermID{"member", "place"}},
	{ID: "refresh.state", Commands: []string{"refresh"}, Statement: bilingual("%s: {{status}}=%q; wait until the agent is idle or done", "%s はいま %q です。idle か done になってから実行してください"), Detail: true, ErrorKey: "error.reset_before_refresh", Slots: []TermID{"member", "status"}},
	{ID: "apply.env-changed", Commands: []string{"apply"}, Statement: bilingual("%s's environment changed, so hergy cannot {{apply}} it. [[env.fixed]]", "%s の環境変数が変わり、{{apply}}できない。[[env.fixed]]"), Detail: true, ErrorKey: "apply.refused_env", Slots: []TermID{"member"}},
	{ID: "apply.state", Commands: []string{"apply"}, Statement: bilingual("%s is working or {{waiting-for-permission}}, so hergy cannot {{apply}} it now", "%s は{{working}}か{{waiting-for-permission}}なので、今は{{apply}}できません"), Detail: true, ErrorKey: "apply.refused_state", Slots: []TermID{"member"}},
	{ID: "apply.removed", Commands: []string{"apply"}, Statement: bilingual("%s is no longer in the {{team-definition}}. Stop the {{team}} and {{start}} it again to {{apply}} this (hergy down, then hergy up)", "%s は{{team-definition}}にありません。{{apply}}するには、{{team}}を終了して{{refresh}}てください（hergy down、hergy up）"), Detail: true, ErrorKey: "apply.refused_removed", Slots: []TermID{"member"}},
	{ID: "up.name-taken", Commands: []string{"up"}, Statement: bilingual("a {{team}} named %s is already running; {{start}} it under another name", "%s という名前の{{team}}がすでに動いています。別の名前で{{start}}してください"), Detail: true, ErrorKey: "error.team_name_taken", Slots: []TermID{"team-name"}},
	{ID: "hire.purpose-outside", Commands: []string{"hire"}, Statement: bilingual("%[1]s cannot hire for \"%[2]s\"; it may hire for: %[3]s (team.yaml workers:). Pass one of those {{purpose}}s", "%[1]s は{{purpose}}「%[2]s」で{{worker}}を呼べません。呼べる{{purpose}}: %[3]s（team.yaml の workers:）。この中の{{purpose}}を指定してください"), Detail: true, ErrorKey: "error.hire_purpose_outside", Slots: []TermID{"member", "purpose", "purpose"}},
	{ID: "hire.purpose-nobody", Commands: []string{"hire"}, Statement: bilingual("no {{member}} may hire a {{worker}} for \"%s\"; who may hire for what: %s. Pass one of those {{purpose}}s", "{{purpose}}「%s」で{{worker}}を呼べる{{member}}はいません。呼べる{{purpose}}: %s。この中の{{purpose}}を指定してください"), Detail: true, ErrorKey: "error.hire_purpose_nobody", Slots: []TermID{"purpose", "member"}},
	{ID: "hire.from-many", Commands: []string{"hire"}, Statement: bilingual("--from is required ({{member}}s hiring for this purpose: %s)", "--from を指定してください（この{{purpose}}の{{worker}}を持つ{{member}}: %s）"), Detail: true, ErrorKey: "error.from_required_many", Slots: []TermID{"member"}},
	{ID: "pane.env", Commands: []string{"refresh", "apply", "up", "hire"}, Statement: bilingual("[[env.fixed]] {{refresh}} keeps the pane and its env. Every pane hergy makes gets GY_ACTOR=<{{herdr-name}}>; a {{profile}}'s own GY_ACTOR does not win, and validate warns when a {{profile}} writes it.", "[[env.fixed]] refresh は同じペインと env を使う。作るペインには GY_ACTOR=<{{herdr-name}}> を設定する。{{profile}}の GY_ACTOR は使わず、validate が警告する。"), Detail: true},
	{ID: "serve.write", Commands: []string{"serve"}, Statement: bilingual("The listener accepts this machine only. Host must be 127.0.0.1 or localhost. A write is a POST, PUT or DELETE carrying this run's X-Hergy-Token. When Origin is sent, it must name the same server. The rendered page holds the token; read it there first.", "この機械からの接続だけを受ける。Host は 127.0.0.1 か localhost。書き込みの POST・PUT・DELETE は、この起動の X-Hergy-Token を持つ必要がある。Origin があれば、同じサーバーを指す必要がある。トークンは配った画面から読む。"), Detail: true},
	{ID: "down.release-cleanup", Commands: []string{"down"}, Statement: bilingual("After closing a {{team}}'s panes, {{down}} waits up to 30000 ms in total for herdr to forget their names. A timeout fails and lists the remaining names. From a {{team}} pane, it waits for the other names before closing your own pane last; your own name cannot be awaited. On timeout it keeps your own pane open: run hergy down again after the names disappear. For a {{team}}, both the CLI and screen list remaining worktrees and clear its turn state, pending signals and {{tell}}s on success or a name-release timeout; a timeout still fails. A screen {{stop}} also cancels this serve's pending {{start}} of that {{team}}. An empty {{team}} tab can be stopped by either entry point without closing the tab itself. The screen reports only {{member}} and {{worker}} panes actually closed; the watcher is excluded. Other errors {{stop}} before this cleanup. For one {{worker}}, {{down}} waits for herdr to forget its name before reporting success; a timeout fails, so a following hire does not reuse a name still held. A name that is both a {{team}}'s and a {{worker}}'s is refused, naming both.", "{{team}}のペインを閉じたあと、herdr から名前が消えるまで全員で最大 30000 ミリ秒待つ。\n時間切れなら、残った名前を示して失敗で終わる。{{team}}のペインから打つと、ほかの名前が\n消えたあとに自分のペインを最後に閉じる。自分の名前は待てない。時間切れなら自分の\nペインを残す。名前が消えたあと hergy down をもう一度打つ。\n{{team}}の終了は、名前の待ちが時間切れでもワークツリーを一覧にし、ターンの記録を\n消してから失敗で終わる。ほかのエラーでは、一覧表示と記録の消去をしない。\n{{worker}}1人の終了は、herdrから名前が消えるまで待つ。時間切れなら失敗で終わる。"), Detail: true},
	{ID: "down.leftovers", Commands: []string{"down"}, Statement: bilingual("After closing, it lists the git worktrees that came while the {{team}} was running (after the {{worker}} was hired, for one {{worker}}), other than the project root: an agent keeps its pane in the project root and cds into a worktree, so the pane's own directory is not enough to find them. The time comes from the {{launch-record}}, and a worktree a closed pane stood in is marked. Each worktree comes with its branch, uncommitted changes and commits not in main, and the project's stashes, with the commands that remove them; hergy removes nothing, and temporary documents are not listed (hergy cannot {{tell}} which are the {{team}}'s).", "閉じたあと、{{team}}が動いている間にできた git ワークツリー（{{worker}} 1 人を閉じたときは、\nその{{worker}}を雇ったあとにできたもの）を、プロジェクトのルートを除いて一覧にする。\nエージェントはペインの作業ディレクトリをルートに置いたまま cd してワークツリーで働くので、\nペインの作業ディレクトリだけでは見つからない。できた時刻は{{start}}の記録から読み、ペインの\n作業ディレクトリがそこにあったワークツリーには、そう添える。一覧の中身は、枝・保存して\nいない変更・main に入っていないコミットの数と、このプロジェクトの stash の数、消すコマンド。\nhergy は消さない。一時文書は、どれが{{team}}のものか分からないので一覧に入れない。"), Detail: true},
	{ID: "team.identity", Commands: []string{"up", "down", "status", "apply", "refresh", "reprompt", "hire", "new", "show"}, Statement: bilingual("A {{team-definition}} is a directory, {{team}}s/<definition>/ under .hergy/ or ~/.config/hergy/. A running\n{{team}} has a {{team}} name: the {{team-definition-name}} by default, or another name given\nto hergy up --as. Commands that read or write a {{team-definition}} take a {{team}}\ndefinition name (up, new, show); commands that act on a running {{team}} take a {{team}}\nname ({{down}}, {{status}}, {{apply}}, {{refresh}}, {{reprompt}}, hire). A running {{team}}'s tab is labelled\nwith the {{team}}'s name alone, and a {{team}} command finds the definition behind it in\nthis machine's {{launch-record}} ($XDG_STATE_HOME/hergy/launches/log.jsonl). The record\nalso keeps one line for each {{worker}} a {{member}} hired, naming the {{member}} that added\nit. A tab is\none of hergy's when a live agent or a named pane in it is named after its label\n(\"<{{team}}>-<{{member}}>\"), or when it still has the older shape\n\"team:<{{team}}>@<definition>\" (\"team:<{{team}}>\", where the definition name is the {{team}}\nname): a {{team}} booted by an older hergy is still found from its label, and another\ntool's tab, or a person's tab that happens to carry a {{team}}'s name, is not a {{team}}.\nWhen herdr's agent list cannot be read at all, a label this machine recorded a\nlaunch of is taken as a {{team}}'s instead.\n", "{{team-definition}}は .hergy/ または ~/.config/hergy/ の teams/<{{team-definition-name}}>/ にある。{{team-name}}は既定で{{team-definition-name}}、hergy up --as で別名を付けられる。定義を扱う up・new・show は{{team-definition-name}}を、動いている{{team}}を扱うコマンドは{{team-name}}を使う。{{team}}のタブは{{team-name}}で表示し、{{launch-record}}から元の定義を読む。hergy が名付けたエージェントかペインがタブにあれば{{team}}として扱う。古い team:<{{team-name}}>@<{{team-definition-name}}> の形も読む。エージェント一覧が読めないときは、この機械の{{launch-record}}にあるタブ名を使う。")},
	{ID: "reference.running-against-herdr", Commands: []string{"up", "down", "apply", "refresh", "reprompt", "hire", "focus", "nudge", "stop", "tell"}, Statement: bilingual("  focus, nudge, {{stop}} and {{tell}} read and drive herdr from anywhere; the pane you type in says who a message is from, and a {{member}} running in it cannot {{stop}} itself.", "focus・nudge・stop・tell は herdr のペインの外からも使える。{{team}}を指定しなければ、動いている{{team}}を解決する。見つからないか複数なら候補を示して断る。{{launch-record}}は元の{{team-definition}}を示す。")},
	{ID: "reference.reading-the-output", Commands: []string{"up", "down", "status", "refresh", "reprompt", "apply", "focus", "nudge", "stop", "tell", "hire", "turns", "turn-done", "ls", "show", "new", "migrate", "validate", "serve", "version", "cheat"}, Statement: bilingual("Most lines are \"name: value\" (for example \"team: demo\", or \"{{team-definition}}: demo\" for a {{team-definition}}). The field names are translated by --lang, so a Japanese run prints \"チーム: demo\".\n  The values, the JSON keys and the \"next:\" line are never translated.\n  A line \"next: <command>\" names the command to type next, with no leading hergy (for example \"next: {{down}} demo\", or \"next: {{status}} demo\" after up --as demo).\n  --dry prints the plan; with --json it is an object with these top-level keys:\n    up (mode=boot): always: mode, {{team}}, startup_timeout_ms, {{member}}s, turns\n    {{refresh}} (mode=restart): always: mode, {{team}}, startup_timeout_ms, {{member}}s, turns\n    {{reprompt}} (mode={{reprompt}}): always: mode, {{team}}, startup_timeout_ms, {{member}}s, turns\n    hire (mode=spawn): always: mode, {{team}}, startup_timeout_ms, {{member}}s, turns\n    {{apply}}: always: herdr, count, {{team}}s\n    {{down}}: always: {{team}}, {{member}}s, {{worker}}s, leftovers\n  {{apply}} returns the same shape as GET /api/{{apply}}, which the screen's {{apply}} sheet reads.\n  {{status}} --json prints its rows as JSON, the one command that does not need --dry: a {{team}} object with {{member}}s, each {name, state, unchanged_minutes, live, {{worker}}}, where unchanged_minutes is the number of minutes a working {{member}}'s screen has stood (absent when it changed or hergy had not seen it). With no {{team-name}} it is {\"{{team}}s\": [...]}, one such object each.\n  Members in --dry --json have different shapes:\n    up/{{refresh}}/{{reprompt}}/hire {{member}}s[]: always: name, {{role}}, {{kind}}, args, env, cwd, prompt, segments, {{profile}}; optional: turns, {{worker}}s, sources\n    {{apply}} {{team}}s[].{{member}}s[]: always: name, short, {{role}}, state, how, changes, can_apply, conversation_lost; optional: why_not\n    {{down}} {{member}}s[]: {{herdr-name}} strings\n  For up, {{refresh}}, {{reprompt}} and hire, optional {{member}} keys appear only when set; cwd is an absolute path, and env is the pane's environment, the {{profile}}'s own variables plus GY_ACTOR. For {{apply}}, why_not appears only when the {{member}} cannot be applied.\n  Exit codes: 0 success; 1 a failure, or validate finding a broken file; 130 interrupted with Ctrl-C.", "表示の項目名は --lang に従うが、値・JSON のキー・next の行は翻訳しない。next は続けるコマンドを示す。--dry --json は操作の計画、status --json は{{status}}の行を JSON で表示する。終了コードは成功0、失敗と壊れた設定1、Ctrl-C は130。")},
	{ID: "reference.web-ui", Commands: []string{"serve"}, Statement: bilingual("  The screens, one line each:\n    /             moves to /{{activity}} while this project has a {{team}} running, else to /{{team}}s\n    /{{activity}}     this project's running {{team}}s: one tile per {{team}}, with its state, diagram and {{member}}/{{worker}} counts. Each tile links to the launch definition by its name and {{place}}, uses that same definition for its diagram, and opens the {{apply}} sheet, or asks for the {{stop}} in a confirmation dialog first, which names the panes it closes (the {{stop}} sheet then shows the result); waiting and stalled rows select and scroll to their tile. The screen reads itself again every ten seconds. /{{activity}}?open=<{{team}}>,… selects the named {{team}}. Applying selected {{member}}s has the same result as hergy apply.\n    /{{team}}s        the {{team-definition}}s: the list (name, {{description}}, {{place}}, and the counts of its {{member}}s and {{worker}}s, and {{rule}}s size), a head for each {{place}} (the project's, each listed project's, and グローバル) with ＋ <{{place}}> にチーム定義を追加 on it (the new row opens at the top of that head, with a name to fill in, and the team.yaml and agreement.md it would write listed; the {{member}}s' {{role}}s and {{profile}}s are picked from what either {{place}} holds, and the starter {{role}}s and {{profile}} are written only when the person presses the button for them, and then only the starter names the row's {{member}}s use), and each row carrying 複製, グローバルにコピー / プロジェクトにコピー and 削除 ; a row opens in {{place}} with the two tabs トポロジー (team.yaml as a figure: the {{human}} and the {{member}}s as points, the turns as lines; a turn is added or taken away by pressing a point or a line, a card shows what the change would do to the prompt before it is made, a {{member}}'s card carries 複製, which adds the same {{member}} again (its {{role}}, {{profile}}, turns and {{worker}} {{purpose}}s) under the next free name, and the team.yaml the row would write is shown line by line beside the figure) and 規則 (the {{team}} document and its shared {{role}}s side by side)\n      [[web.prompt-preview]]\n    /{{team}}s?open=name|{{global}} or /{{team}}s?open=name|<current project absolute path> opens only the specified {{place}} even without listed projects. Without listed projects, another project or a definition absent from that {{place}} shows the existing not-found message. Opening a row writes open=name|{{place}} (a project row is open=name|project), and opening that URL again opens the same row. An old URL with no {{place}} opens both rows of that name, the project's and the {{global}} one.\n    /{{team}}s/yaml   every team.yaml and agreement.md as text, the project's and the one outside it, with line numbers and validate's problems beside the editor\n    /{{profile}}s     the {{profile}}s: the list (name, {{kind}}, {{place}}, args, env and who uses it), a row that opens and is written in {{place}}, and the {{kind}} chips and search above it\n    /{{profile}}s/assign  the {{member}}s' and {{worker}}s' {{profile}}s, one card per {{team-definition}}; a pick is saved into that team.yaml\n    /{{profile}}s/yaml  both profiles.yaml files as text, line numbers and validate's problems beside the editor\n    /{{profile}}s/<{{profile}}>  the row of that {{profile}}, opened\n    /{{role}}s        the three tabs of the {{role-document}}s: 一覧 (every {{role}}, the people that read it, its {{rule}}s and character count), 割り当て (each {{team-definition}}'s {{member}}s and the {{role}} each plays) and Markdown (a {{role-document}} as text with validate's problems beside the editor)\n    /{{role}}s/assign  each {{team-definition}}'s {{member}}s and their {{role}}s; a pick is saved into that team.yaml\n    /{{role}}s/yaml  one {{role-document}} as text, with line numbers and validate's problems beside the editor\n    /{{role}}s?open=<{{role}}>  the list tab with that {{role}}'s row opened\n  A band stands at the top of every screen: the hergy logo with a robot face and pen lettering (a link to /) with the project's folder name, then the four screens, all of them pressable. アクティビティ carries アクティビティ N and 待ち N beside it while this project has a {{team}} running: N how many of its {{team}}s are running, and how many of them wait for a {{human}} or a permission. The screen a person is on is the dark one, and the band shows a dot beside a screen that holds changes no save wrote. A team.yaml, {{role-document}} or profiles.yaml that cannot be read stays in its list as one row that says why (the same problem line the {{team}} screen draws), and the band counts that row. 元に戻す on an unsaved edit goes at once and shows 取り消す in {{place}}; 取り消す brings the discarded edit and the unsaved mark back. The figure's 外す of a {{member}}, a turn or a {{worker}}, the conflict's 元に戻す and the ［プロジェクト］ button's 外す also show 取り消す where the person pressed, and ⌘Z in the figure takes back the newest operation too. The ［プロジェクト］ sheet lists and unlists projects: 外す changes no file of that project, and its 取り消す puts the project back at the position it stood in config.yaml's projects: list, comments and all.\n  Walking from one screen to the other with the band carries the changes that were not saved yet, and puts them back when that screen comes round again.\n  What the fields write today: a {{role-document}}, a {{team-definition}}'s team.yaml and its agreement.md, and the two profiles.yaml files (a {{profile}}'s name, {{kind}}, args and env, and the {{profile}} each {{member}} and {{worker}} runs).\n  Waiting rows show each {{member}}'s question or recognized approval block, including its command, without terminal history. Approval blocks require exactly one recognized heading and one consecutive set of numbered choices at the end of the screen; unrecognized boundaries or here-documents direct the person to the terminal. 端末で返答する moves to that {{member}}'s pane, without sending an answer, and shows progress while waiting. The {{activity}} figure shows the selected {{member}}'s turns and separates the {{worker}}s below.\n  YAML and assignment tabs name 表示するプロジェクト and let the person switch among listed projects; reads and saves use that project. Switching projects or leaving a {{profile}} tab asks before discarding unsaved changes. The selected project survives a visit to Activity. An optional {{team-agreement}} with no sections guides the person to ＋ 節. The screens say 設定の検査 and 改訂番号; the meter line is a provisional guide, not a save/{{start}} limit.\n  The {{team-definition}} editor offers a separate 名前を変更 action. Save or {{revert}} that definition’s unsaved edits first. The server refuses running or starting {{team}}s, an unreadable herdr session, a same-place name collision, invalid names, or changed {{team}}/agreement files. Global definitions are checked against the entire connected session, including projects not shown. Names may shadow the other {{place}} with an explanation; {{launch-record}}s keep the old name, and the old URL has no redirect. On macOS and Linux, {{start}}s use shared file locks and renames use exclusive locks under $XDG_STATE_HOME/hergy/team-locks (or ~/.local/state/hergy/team-locks). Concurrent {{start}}s are allowed. Only a lock conflict refuses a {{start}}; unavailable locking does not {{stop}} it. A rename requires its locks. An unknown launch source refuses a rename only when the definition name matches.\n  [[web.role-inline]]\n  The screens the old WebUI had are gone. /definitions and /agreement, and every path under them, answer 404 with the band on the page and one line saying there is no such screen, as do /{{team}}, /running, /{{rule}}s, /diff, /bump, /figure and /panel. The old files /static/hergy.css and /static/htmx-2.0.4.min.js are gone too. A page that is still there moves instead: /{{profile}}s/<name>, and /{{role}}s/<{{role}}> with /new or /<{{rule}}> behind it, go to the list with that {{profile}} or {{role}} opened.", "WebUI の画面（hergy serve で開く。上の帯で切り替える）\n  {{activity}}       /activity（動いている{{team}}を札で確認。各札から{{team-definition}}を開く、{{apply}}していない変更を{{apply}}する、{{team}}を{{down}}）\n  {{activity}}の定義リンクと図は、{{start}}元の{{team-definition}}の名前と{{place}}で選びます\n  {{team-definition}}のURLで open=名前|global または open=名前|今のプロジェクトの絶対パス を指定すると、プロジェクトを列挙しない表示でも指定した{{place}}だけを開きます。列挙しない表示では、別のプロジェクトや指定先に無い定義は「見つかりません」と表示します。画面で行を開くと、URL は open=名前|{{place}}（プロジェクトの行は open=名前|project）で書き、開き直すと同じ行だけが開きます。{{place}}の無い古いURLは、その名前の行を両方（プロジェクトと{{global}}）開きます\n  {{team-definition}}           /teams（トポロジーと{{rule}}。YAML は /teams/yaml）\n  {{profile}}         /profiles（割り当ては /profiles/assign、YAML は /profiles/yaml）\n  {{role}}               /roles（同じ）\n  / で開くと           動いている{{team}}があれば{{activity}}（/activity）、無ければ{{team-definition}}（/teams）\n\n\n  {{team-definition-name}}の変更は、編集画面の「名前を変更」から名前だけを保存します。未保存の編集がある間、{{team}}が動いている間、herdrの{{status}}を確認できない間は変更できません。{{start}}の記録は変更前の名前で残ります。\n  [[web.role-inline]]\n\n  帯の hergy ロゴは、ロボットの顔とペン字の文字で、ホームへのリンクです。動いている{{team}}があれば{{activity}}、無ければ{{team-definition}}を開きます。読めない（壊れた・権限の無い）team.yaml・{{role-document}}・profiles.yaml は、一覧に 1 行として残り、{{reason}}を読めます。帯の件数はその行も数えます。保存していない編集の「{{revert}}」はすぐに戻し、その場に「{{undo}}」を出します。{{undo}}と、捨てた編集と未保存の印が戻ります。{{team-definition}}・{{role}}・{{profile}}の削除、入力のある新しい行の取り消し、{{team}}の終了、保存していない変更を残したままの移動は、1 つの確認で確かめます。確認には消えるもの（消えるファイル、フォルダに残るファイル、閉じるペイン、使う人数）が出て、「削除する」「{{down}}」「破棄する」を選んだときだけ行います。図の{{member}}・ターン・{{worker}}の「外す」、競合の「{{revert}}」、［プロジェクト］の「外す」も、その場に「{{undo}}」を出します。図は ⌘Z でも 1 つ戻ります。［プロジェクト］の「外す」はそのプロジェクトのファイルを変えず、「{{undo}}」で config.yaml の元の位置（コメントも）に戻ります。\n\n  同じ{{team-definition}}からの{{start}}どうしは妨げません。ロックを保存できない場合は名前変更を断りますが、{{start}}は続けます。\n\n  [[web.prompt-preview]]\n")},
	{ID: "reference.resolution", Commands: []string{"up", "down", "status", "refresh", "reprompt", "apply", "focus", "nudge", "stop", "tell", "hire", "turns", "turn-done", "ls", "show", "new", "migrate", "validate", "serve", "version", "cheat"}, Statement: bilingual("  The project root is the git root (else the current directory); -C, --dir overrides it. Definition file paths in displays and new {{launch-record}}s use their canonical absolute spelling, resolving symlinks. Existing records retain their saved spelling and compare by canonical identity.\n  Relative and absolute paths, trailing slashes and symbolic-link aliases name the same project. Project paths shown by the CLI and API use the normalized absolute spelling.\n  hergy's own state is $XDG_STATE_HOME/hergy (or ~/.local/state/hergy when unset): launches/log.jsonl records up, {{apply}}, {{refresh}} and {{reprompt}}, and launches/blobs/<sha256> holds the prompt texts and {{rule}} file contents each line points at. Members are confirmed recipients only. After success or missing receipts, up (including {{start}}s from the screens) records the {{team}} even when no prompt was received; {{refresh}}, {{reprompt}} and {{apply}} write only with at least one confirmed recipient. Other sending/startup failures and cancellation write none. A launch that cannot be recorded still runs, with one line on stderr.", "{{team-definition}}と設定は、プロジェクトの .hergy/ と $XDG_CONFIG_HOME/hergy（未設定なら ~/.config/hergy/）から読む。同じ名前はプロジェクトを{{preferred}}する。プロジェクトの場所は git のルート、無ければ現在のディレクトリ。-C・--dir で指定する。パスは絶対パスに正規化し、シンボリックリンクも同じプロジェクトとして比べる。新しい表示と{{launch-record}}は正規化後のパスを使う。古い記録の綴りは変えない。")},
	{ID: "reference.team-definition-and-member-names", Commands: []string{"up", "new", "hire", "validate"}, Statement: bilingual("{{member}}s[].name is a short {{member-name}} (lead, builder). hergy prefixes the {{team-name}}, so the {{herdr-name}} is <{{team}}>-<{{member}}>.\n  --as <{{team}}> runs the same {{team-definition}} under another name: the demo definition's lead is demo-lead, and dev2-lead with --as dev2.\n  {{apply}} <{{member}}>, {{refresh}} <{{member}}>, {{reprompt}} <{{member}}>, focus <{{member}}>, nudge <{{member}}>, {{stop}} <{{member}}>, {{tell}} <{{member}}> and hire --from <{{member}}> accept the short {{member-name}} or the {{herdr-name}}; the short name is {{preferred}}.\n  The pattern [a-z][a-z0-9_-]{0,24} is checked by new and --as only; what always holds is that <{{team}}>-<{{member}}> matches [a-z][a-z0-9_-]{0,31}.", "{{team-name}}と{{team-definition-name}}は [a-z][a-z0-9_-]{0,24}。{{member-name}}と{{worker}}名は [a-z][a-z0-9_-]{0,31}。できあがる {{herdr-name}}も [a-z][a-z0-9_-]{0,31} に収まる必要がある。{{kind}} は [a-z][a-z0-9_-]*、{{profile-name}}と{{role-name}}は [a-z][a-z0-9_-]{0,31}。{{role}}の表示名は文書の先頭行。環境変数の値は文字列で、数値は引用符で囲む。変数名は [A-Za-z_][A-Za-z0-9_]*。members[].name に %{team} は書けない。prompt が無ければ既定のひな形。空白だけの prompt と未知の置換は断る。")},
	{ID: "reference.settings-files-and-their-keys", Commands: []string{"up", "apply", "refresh", "reprompt", "hire", "validate", "serve", "new", "show"}, Statement: bilingual("Unknown keys are an error in every settings file. {{kind}} matches [a-z][a-z0-9_-]*; a {{profile-name}} matches [a-z][a-z0-9_-]{0,31}; a {{role-name}} matches [a-z][a-z0-9_-]{0,31} too, and the name people read is the {{role-document}}'s title. A {{role-document}} whose name is not a {{role-name}} is broken: validate says so, and up of a {{team}} that reads it {{stop}}s.\n  env values must be strings (quote numbers); an env name matches [A-Za-z_][A-Za-z0-9_]*.\n  {{member}}s[].name must not contain %{team}. A missing prompt uses the built-in template; a whitespace-only prompt is an error; an unknown %{x} is an error.\n  Global config.yaml, at <global>/config.yaml:\n    version: 1        required, int; must be 1.\n    lang: en|ja       string; the language when --lang is not given; default en.\n    projects:         list of directories, optional; the projects hergy serve shows as its {{headquarters}} (d-73fc). Each entry is an absolute path or {{start}}s with ~/; ~ is expanded when read. Without the key, serve shows the project it was started in and the {{global}} settings. With an empty list it shows the {{global}} settings alone. A relative path is a broken setting that validate and serve refuse.\n  A {{team-definition}}'s team.yaml, at teams/<definition>/team.yaml under .hergy/ or ~/.config/hergy/; cwd is relative to the project root:\n    version: 1        required, int; must be 1.\n    description: \"<text>\" string, required; one line saying which case the {{team}} is meant for. A definition that writes none, or writes one over more than one line, does not read, and one that still writes the key it replaced is stopped with the sentence that says to write description: instead; hergy validate warns while it is still the starter example hergy new writes. The {{place}}s a person picks or reads a definition read it (the {{team}} list, a definition's screen, the {{start}} sheet, hergy show); a {{team}} command's header and a running {{team}}'s tiles do not, and it is never part of a {{member}}'s prompt or of what hergy apply puts right.\n    team: <definition> string, optional; if written it must equal the {{team-definition-name}} (the directory name).\n    cwd: <dir>        string; working directory, relative to the project root; default \".\".\n    prompt: \"<text>\"  string, optional; the {{bootstrap-prompt}} template for every {{member}}. It must keep %{role_doc} and %{docs}.\n    members:          required, nonempty list.\n      name: <{{member}}>     required, string; short {{member-name}} matching [a-z][a-z0-9_-]{0,31}.\n      role: <{{role}}>       required, string; a {{role-name}} matching [a-z][a-z0-9_-]{0,31}; the name people read is the document's title. Reads roles/<role>.md (the project's first, then ~/.config/hergy/).\n      profile: <name>    required, string; a named engine from profiles.yaml. {{kind}}, args and env are the {{profile}}'s: writing one of them on a {{member}} is an error that says where it goes.\n      cwd: <dir>         string; overrides the {{team}} cwd.\n      prompt: \"<text>\"   string; overrides the {{team}} prompt. It must keep %{role_doc} and %{docs}.\n    workers:          list, optional; which {{member}} may hire which {{worker}}. Each entry ties one {{worker}} to the {{member}} that hires it; the {{worker}}'s two turns (the {{member}} to the {{worker}}, and the {{worker}} back) are made from it and cannot be written in turns:. A {{member}} and a {{purpose}} written twice is an error. A {{worker}} has one purpose: write two {{purpose}}s as two entries (the same {{profile}} may be written twice), and a {{purpose}} with a comma or a Japanese comma {{stop}}s the definition.\n      - from: <{{member}}>     required, string; the {{member}} that hires this {{worker}}.\n        purpose: <text>    required, string; what the {{worker}} is for; one {{purpose}} per {{worker}}, and one {{worker}} per {{member}} and {{purpose}}.\n        profile: <{{profile}}> required, string; the engine that {{worker}} runs; a {{profile}} in profiles.yaml.\n    turns:            list, required; who {{hands-the-turn-to}} whom, one entry per turn, written \"- <from> -> <to>\". Each end is a {{member}}'s name, or {{human}}. A turn graph hergy cannot hold {{stop}}s the definition, the way a file that does not read does: the same sentences {{stop}} up, {{apply}}, {{refresh}}, {{reprompt}}, hire and validate, one per line, and {{down}} still closes such a {{team}} by name. What {{stop}}s it is a name that is no {{member}} and no {{human}}, a name written \"<{{kind}}>:<name>\" (no {{kind}} but {{human}} and a {{member}} may stand there yet), a turn to itself, the same turn twice, a {{member}} or the {{human}} that {{hands-the-turn-to}} nobody, and no turn reaching the {{human}}. Arrows in {{rule}} text are not interpreted or compared with turns:.\n    ledger:           list, optional; which {{member}} may make which write to gy, one {{rule}} per entry, written \"<write> by <{{member}}>[, <{{member}}>...]\". <write> is the name of a gy write, the first two words of the why it records: req add, req approve, req done, req revise, criterion satisfy, need add, need close, decide, question add, question close, or \"question to {{human}}\" for a question whose decider is no {{member}} of the {{team}}. <{{member}}> is a {{member}}s[].name; a {{worker}}'s name cannot be written (a {{worker}} takes no {{rule}}s). It moves no exit code: hergy validate warns once for each write a writer of the {{team}} (GY_ACTOR begins with the {{team-name}}, or the name the {{launch-record}} shows) made that the {{rule}} gives to other {{member}}s, and when gy cannot be read it says so in one line instead.\n  Where a {{member}}'s documents are (team.yaml has no key for them):\n    roles/<role>.md                 under .hergy/ or ~/.config/hergy/: a {{member}}'s {{role-document}}; read first. The project's first, then outside it.\n    teams/<definition>/agreement.md the {{team}}'s own agreement; read next. Optional.\n    agreement.yaml at the top of .hergy/ or ~/.config/hergy/ is not read any more (the agreement every {{team}} used to share). While one is left, up, {{apply}}, {{refresh}}, {{reprompt}} and hire {{stop}} before they build a prompt, naming the file and where the {{rule}}s go, and validate names it; move the {{rule}}s into a {{team}}'s agreement or a {{role-document}}, then remove the file.\n  profiles.yaml, at .hergy/profiles.yaml or ~/.config/hergy/profiles.yaml, next to {{team}}s/:\n    version: 1        required, int; must be 1.\n    {{profile}}s:         mapping of {{profile-name}} to engine.\n      <name>:\n        kind: <{{kind}}>       required, string; herdr's agent {{kind}}.\n        args: [<arg>...]   list of strings; passed to the agent CLI as is. Quote numbers.\n        env: {NAME: value} mapping of string to string; environment for the pane. hergy adds GY_ACTOR itself, so a value written here does not win.\n      A name equal to its {{kind}} reads as a choice of {{kind}}; validate warns on it and says to name the model or the settings.\n  A {{team-definition}} reads the project's profiles.yaml over the one outside it, wherever the definition sits: a {{profile}} of the same name resolves to the project's.", "{{global}}の config.yaml は version: 1、lang: en|ja、任意の projects: を持つ。projects は絶対パスか ~/ で始まるパスを並べ、相対パスは validate と serve が断る。projects が無ければ{{start}}したプロジェクト、空なら{{global}}だけを表示する。\n{{team-definition}}の team.yaml は version: 1、1行の description、空でない members、turns を必須とする。team を書くならディレクトリの{{team-definition-name}}と一致させる。cwd はプロジェクトからの相対パスで既定は .。prompt は %{role_doc} と %{docs} を保つ。{{member}}は name・role・profile を持ち、cwd・prompt を上書きできる。{{kind}}・args・env は{{profile}}に書く。\nworkers は from・purpose・profile の組。{{purpose}}は1人につき1つで、複数なら項目を分ける。カンマや読点を含む{{purpose}}、同じ{{member}}と{{purpose}}の重複は断る。{{worker}}との往復は workers から作り、turns に書かない。\nturns は <from> -> <to> の一覧で、{{member-name}}か human を書く。未知の名前、自分への矢印、重複、渡し先が無い{{member}}と{{human}}、{{human}}へ届かない構成は定義を断る。{{rule}}本文の矢印は解釈しない。\nledger は任意で、<write> by <member>[, <member>...] の一覧。gy の書き込み名か question to human を指定する。{{team}}の GY_ACTOR に当たる書き込みが別{{member}}に割り当てられていれば validate が警告する。gy を読めなければ1行で知らせる。終了コードは変えない。\n{{role-document}}は roles/<{{role-name}}>.md、{{team-agreement}}は任意の teams/<{{team-definition-name}}>/agreement.md。先に{{role}}、次に{{team-agreement}}を読む。古い最上位の agreement.yaml は読まず、残っていれば{{bootstrap-prompt}}の生成を止め、移す先を示す。\nprofiles.yaml は version: 1 と profiles を持ち、各{{profile}}に {{kind}}、文字列の配列 args、文字列同士の env を書く。同じ名前は、{{team-definition}}の{{place}}にかかわらずプロジェクトを{{preferred}}する。GY_ACTOR は hergy が決める。{{profile-name}}が {{kind}} と同じなら、モデルか設定を表す名前にするよう validate が警告する。")},
	{ID: "reference.rule-documents", Commands: []string{"up", "apply", "refresh", "reprompt", "hire", "validate", "migrate", "serve"}, Statement: bilingual("[[web.rule-editing]]\n\n[[web.theme]]\n\n[[documents.body]]\n[[resources.rename]]\n[[resources.definition-copy]]\n[[resources.delete-readers]]\n[[rules.budget]]\n[[rules.migration]]", "[[web.rule-editing]]\n\n[[web.theme]]\n\n[[documents.body]]\n[[resources.rename]]\n[[resources.definition-copy]]\n[[resources.delete-readers]]\n[[rules.budget]]\n[[rules.migration]]")},
	{ID: "reference.bootstrap-prompt-placeholders", Commands: []string{"up", "apply", "refresh", "reprompt", "hire", "show"}, Statement: bilingual("%{team} %{role} %{name}  the {{team-name}}, the {{role}}, and the {{member}}'s name (the {{herdr-name}}, <{{team}}>-<{{member}}>)\n  %{role_doc}  the {{role-document}}     %{docs}  the agreements     %{roster}  the roster\n  %{actor}  the name hergy passes to gy as GY_ACTOR (the {{herdr-name}})\n  %{herdr}  how to {{check}} whether the agent is running inside herdr, reach others, and add a teammate\n  %{turns}  who the {{member}} {{hands-the-turn-to}}, from the definition's turns:\n  %{workers}  what the {{member}} may hire, with the command (only when workers: names one for it). The old %{spawn} is gone: a template that still writes it is an error that says so.", "%{team} は{{team-name}}、%{role} は{{role}}、%{name} は {{herdr-name}}。%{role_doc} は{{role-document}}、%{docs} は{{rule}}、%{roster} は名簿。%{actor} は GY_ACTOR。%{herdr} は連絡の決まり。%{turns} は渡し先。%{workers} は追加できる{{worker}}の{{purpose}}とコマンド。古い %{spawn} は断る。")},
	{ID: "flag.as.up", Commands: []string{"up"}, Statement: bilingual("Start the {{team}} under this {{team-name}} (default: the {{team-definition-name}})\nIt is the first half of the {{herdr-name}}", "この{{team-name}}で{{start}}する（既定は{{team-definition-name}}）\n{{herdr-name}}の前半になる")},
	{ID: "flag.dry.up", Commands: []string{"up"}, Statement: bilingual("Print the plan (each {{member}}'s prompt as text) and {{start}} nothing\n[[dry.offline]]", "{{start}}せず、計画（{{member}}ごとのプロンプト）だけを表示する\n[[dry.offline]]")},
	{ID: "flag.dry.down", Commands: []string{"down"}, Statement: bilingual("Print what would close and close nothing\n[[dry.live]]\nIt never waits for names to disappear", "閉じる予定だけを表示し、何も閉じない\n[[dry.live]]\n名前が消えるのは待たない")},
	{ID: "flag.json.status", Commands: []string{"status"}, Statement: bilingual("Print the rows as JSON (state and unchanged_minutes) instead of text", "行を JSON で表示する（state と unchanged_minutes）")},
	{ID: "flag.all.refresh", Commands: []string{"refresh"}, Statement: bilingual("Restart every {{member}} (not with a {{member}})", "全{{member}}を{{start}}し直す（{{member}}とは同時に指定できない）")},
	{ID: "flag.dry.refresh", Commands: []string{"refresh"}, Statement: bilingual("Print what would restart or be added, and change nothing\n[[dry.live]]. [[refresh.own-pane]]", "{{start}}し直す予定と、足す予定を表示し、何も変えない\nherdr の今の{{status}}を読む。[[refresh.own-pane]]")},
	{ID: "flag.all.reprompt", Commands: []string{"reprompt"}, Statement: bilingual("Send it to every {{member}} (not with a {{member}})", "全{{member}}に送り直す（{{member}}とは同時に指定できない）")},
	{ID: "flag.dry.reprompt", Commands: []string{"reprompt"}, Statement: bilingual("Print what would be sent and send nothing\n[[dry.offline]]", "送る予定だけを表示し、何も送らない\n[[dry.offline]]")},
	{ID: "flag.dry.apply", Commands: []string{"apply"}, Statement: bilingual("Print each {{member}}'s way of applying, what changed and the {{team}}'s {{rule-note}}s\nIt changes nothing; [[dry.live]]\nExit 1 if any {{member}} cannot be applied, including with --json", "{{member}}ごとの{{apply}}の仕方・変わったこと・{{team}}の知らせを表示する\n何も変えない。herdr の今の{{status}}を読む\n{{apply}}できずに残る{{member}}がいれば終了コードは 1（--json でも同じ）")},
	{ID: "flag.dry.nudge", Commands: []string{"nudge"}, Statement: bilingual("Print what would be sent and send nothing\n[[dry.offline]]; the sender is the {{human}}\n(a --dry run cannot read the pane's {{member}})", "送る予定だけを表示し、何も送らない\n[[dry.offline]]。送り主は{{human}}として出す\n（--dry では、打ったペインの{{member}}を読まない）")},
	{ID: "flag.dry.stop", Commands: []string{"stop"}, Statement: bilingual("Print what would {{stop}} and change nothing\n[[dry.offline]]", "{{stop}}予定だけを表示し、何も変えない\n[[dry.offline]]")},
	{ID: "flag.from.tell", Commands: []string{"tell"}, Statement: bilingual("The {{member}} or {{worker}} the message is from (short name or {{herdr-name}})\nLeft out: whoever owns the pane you type in, else the {{human}}", "誰からの本文か（{{member}}か{{worker}}の短い名前か {{herdr-name}}）\n省くと、打ったペインの{{member}}か{{worker}}。それ以外のペインでは{{human}}")},
	{ID: "flag.dry.tell", Commands: []string{"tell"}, Statement: bilingual("Print what would be sent and send nothing\nRead definition {{member}}s only; workers are not resolved. [[dry.offline]]\nWithout --from the sender is the {{human}}", "送る予定だけを表示し、何も送らない\n定義の{{member}}だけを使い、[[dry.offline]]。{{worker}}は解決しない\n--from が無ければ送り主は{{human}}")},
	{ID: "flag.purpose.hire", Commands: []string{"hire"}, Statement: bilingual("What the {{worker}} is for (required)\nA {{purpose}} the hiring {{member}}'s workers: names;\nthe {{profile}} comes from that entry", "{{worker}}の{{purpose}}（必須）\n呼ぶ{{member}}の workers: が名指す{{purpose}}であること。\n{{profile}}はその組から決まる")},
	{ID: "flag.task.hire", Commands: []string{"hire"}, Statement: bilingual("The task text handed to the {{worker}} (required)", "{{worker}}に渡す依頼の文（必須）")},
	{ID: "flag.from.hire", Commands: []string{"hire"}, Statement: bilingual("The {{member}} that hires the {{worker}} (short {{member-name}} or {{herdr-name}})\nLeft out: required unless exactly one {{member}} hires for this {{purpose}}", "{{worker}}を追加する{{member}}（短い{{member-name}}か {{herdr-name}}）\nこの{{purpose}}の{{worker}}を持つ{{member}}が1人だけなら省ける")},
	{ID: "flag.dry.hire", Commands: []string{"hire"}, Statement: bilingual("Print the plan and {{start}} nothing\nThe {{team}} is the one --team names (a {{team-name}}, or a {{team}}\ndefinition name the {{launch-record}} does not know), else the one\n{{team}} in this project's {{launch-record}}. [[dry.offline]], so a {{team}}\nthat is not running can be planned for", "{{start}}せず、計画だけを表示する\n{{team}}は --team が名指すもの（{{team-name}}か、{{start}}の記録に無い\n{{team-definition-name}}）。無ければ、このプロジェクトの{{start}}の記録にある1つの\n{{team}}。[[dry.offline]]ので、動いていない{{team}}も計画できる")},
	{ID: "flag.log.turns", Commands: []string{"turns"}, Statement: bilingual("Print the watcher's log (each line with its time) and {{stop}}\nThe pane shows the band; the sentences are in turns/<team>.log", "見張りのログ（1 行ごとに時刻付き）を表示して終わる\nペインには帯だけが出る。文は turns/<{{team}}>.log に残る")},
	{ID: "flag.dry.migrate", Commands: []string{"migrate"}, Statement: bilingual("Inspect every conversion without writing", "全対象を検査して表示する。書き込まない")},
	{ID: "flag.global.migrate", Commands: []string{"migrate"}, Statement: bilingual("Convert {{global}} settings instead of the project", "プロジェクトではなく{{global}}を変換する")},
	{ID: "flag.port.serve", Commands: []string{"serve"}, Statement: bilingual("The port to listen on (default 8787; 0 lets the operating system pick a free one)", "待ち受けるポート（既定は 8787。0 は空きポートを OS が選ぶ）")},
	{ID: "flag.no-open.serve", Commands: []string{"serve"}, Statement: bilingual("Print the URL and open no browser", "URL を出すだけで、ブラウザを開かない")},
	{ID: "flag.ai.cheat", Commands: []string{"cheat"}, Statement: bilingual("Print the whole of hergy for an agent instead (always English)", "代わりに、AI 向けの全量（英語）を表示する")},
	{ID: "flag.lang", Commands: []string{"up", "down", "status", "refresh", "reprompt", "apply", "focus", "nudge", "stop", "tell", "hire", "turns", "turn-done", "ls", "show", "new", "migrate", "validate", "serve", "cheat"}, Statement: bilingual("Language of the command line's output (default en)\nThe WebUI is Japanese", "コマンドの出力の言語（既定は en）\nWebUI は日本語")},
	{ID: "flag.help", Commands: []string{"up", "down", "status", "refresh", "reprompt", "apply", "focus", "nudge", "stop", "tell", "hire", "turns", "turn-done", "ls", "show", "new", "migrate", "validate", "serve", "cheat"}, Statement: bilingual("Show this text", "この{{description}}を表示する")},
	{ID: "flag.dir", Commands: []string{"up", "down", "status", "refresh", "reprompt", "apply", "focus", "nudge", "stop", "tell", "hire", "turns", "turn-done", "ls", "show", "new", "migrate", "validate", "serve"}, Statement: bilingual("The project root to resolve against\n(default: the git root, else the current directory)", "プロジェクトの場所を指定する\n（既定は git のルート。なければ今のディレクトリ）")},
	{ID: "flag.json", Commands: []string{"up", "down", "refresh", "reprompt", "apply", "hire"}, Statement: bilingual("With --dry, print the plan as JSON (--dry is required)", "--dry の計画を JSON で表示する（--dry が必要）")},
	{ID: "startup.timeout", Commands: []string{"up", "refresh", "apply", "hire"}, Statement: bilingual("Startup timeout in milliseconds, 3001..300000 (default 30000)", "{{start}}を待つ時間（ミリ秒。3001〜300000、既定 30000）")},
	{ID: "team.selection", Commands: []string{"refresh", "reprompt", "apply", "focus", "nudge", "stop", "tell"}, Statement: bilingual("The {{team}} to act on, by {{team-name}}. With --dry, a {{team-definition-name}} unknown to the {{launch-record}} is also accepted. With no name, the one running {{team}} is used; when several run, the {{team}} of the current {{member}} pane is inferred when available. A --dry that reads no herdr uses the one {{team}} in this project's {{launch-record}}.", "対象の{{team-name}}。--dry では、{{launch-record}}に無い{{team-definition-name}}も書ける。省くと、動いている{{team}}が1つならそれを使う。複数なら、今の{{member}}のペインから{{team}}を特定できる場合はそれを使う。herdr を読まない --dry では、このプロジェクトの{{launch-record}}にある1つの{{team}}を使う。")},
	{ID: "hire.team-selection", Commands: []string{"hire"}, Statement: bilingual("The {{team}}, by {{team-name}} or {{team-definition-name}}. Left out: with --dry, the one {{team}} in this project's {{launch-record}}; otherwise the running {{team}}, inferred from the current {{member}} pane when several run.", "対象の{{team}}（{{team-name}}か{{team-definition-name}}）。省くと、--dry ではこのプロジェクトの{{launch-record}}にある1つの{{team}}。実行時は動いている{{team}}を使い、複数なら今の{{member}}のペインから特定する。")},
	{ID: "rules.budget", Commands: []string{"validate", "up"}, Statement: bilingual("Each {{role}} and {{team}} has a provisional 1,200-character budget. A {{team}}'s total includes {{rule}}s plus fixed words in {{team}}/{{member}} prompt templates, excluding placeholders and generated text. Count Unicode code points, normalizing CRLF only for counting. Excess is a warning, never a startup failure.", "{{role}}と{{team}}の{{size-guide}}は各1,200文字。{{team}}は{{rule}}と{{bootstrap-prompt}}のひな形の固定文を数え、置換と生成文を除く。Unicode のコードポイントを数え、CRLF は LF として数える。超過は警告で、{{start}}を断らない。")},
	{ID: "rules.migration", Commands: []string{"migrate", "validate"}, Statement: bilingual("There are no {{rule}} IDs, on/off fields or separate {{rule-note}}s. Use hergy migrate --dry, then hergy migrate to convert legacy YAML explicitly, or add --global for {{global}} settings. Adjacent .yaml.bak files retain the original bytes, including excluded {{rule}}s and {{rule-note}}s. Old YAML at an active path {{stop}}s validate and prompt generation. See CHANGELOG for collisions, symlinks, unsupported hard links and recovery.", "旧形式の YAML は hergy migrate --dry のあと hergy migrate で変換する。{{global}}には --global を付ける。隣の .yaml.bak には元のバイト列を残し、除外した{{rule}}と{{rule-note}}も残る。有効な場所の旧 YAML は validate と{{bootstrap-prompt}}の生成を{{stop}}。衝突・シンボリックリンク・ハードリンクと復旧は CHANGELOG を参照する。")},
	{ID: "web.rule-editing", Commands: []string{"serve"}, Statement: bilingual("In the {{team}} screen’s {{rule}}s tab, switch to headings and use a heading’s ⋯ menu to choose another {{team}} or {{role}}, an insertion position, and whether to include child headings. Drag the grip to another column to move; hold Alt (⌥ on Mac) when dropping to copy, or Shift (⇧ on Mac) when starting the drag to include children. The selected text stays unchanged; a missing blank line at the insertion boundary is supplied. Review the drafts and {{undo}} before saving. Moves save the destination first; if saving the source fails, the screen says the text remains in both files. Select a document by its name to read and edit it. The {{rule}}s tab opens with every document of the definition (the {{team}} {{rule}}s and the {{role-document}}s its {{member}}s use) side by side at the standard reading width of about 40 Japanese characters per line in 16px text; the {{role}} screen uses the same standard width. Use 並べる to choose again which documents stand together, or すべて表示 to bring them all back. Switching documents preserves unsaved edits; each document keeps its own save target. Use Narrow or Wide in a column header, and Equal to reset the widths. Wide expands the selected document beyond the standard reading width. Apart from a column narrowed on {{purpose}}, no column is narrower than the standard reading width, and a wide column grows at twice the rate of the others; the board has its own horizontal scrollbar and an explanation when documents do not fit. At narrower widths, two selected documents are stacked. All four screens use the available width for the header and content, with no width limit and at least 40px of space on each side. Below 420px, each side uses at least 16px to leave more room for the content. At 420px and above, the header stays aligned when switching screens. Narrower screens do not reserve space for a scrollbar, so the right side of the header may move when the page length changes. With no focus in an input, the wheel over it scrolls the page; to read inside an input, press it once and then turn the wheel. Ctrl (⌘ on a Mac) with the wheel and pinch stay with the browser's zoom. Switching the display, re-reading, filtering or changing the theme never moves the page; only an act that names its destination (editing the selected attributes, a waiting row, opening a row from a URL) or one whose result would stand off the screen (copy, a new row, a duplicate) brings that destination into view.", "{{team-definition}}の{{rule}}タブでは見出しから宛先・挿入位置・子見出しを含むかを選び、写す・移す。ドラッグは移動、Alt（Mac は ⌥）を押して放すとコピー、Shift（Mac は ⇧）を押してつかむと子見出しも含む。選んだ文は変えず、境目の空行だけを補う。移動は宛先から保存し、元の保存に失敗したら両方に残ったことを示す。文書を切り替えても下書きと保存先は文書ごとに保つ。欄の狭く・広くと全体の均等で幅を変える。標準幅は本文16pxで約40字、狭くした欄以外は標準幅を保つ。広い欄は2倍の伸び率で幅を分け、入らないときは横スクロールで読む。狭い画面では比較する文書を縦に並べる。4画面は幅の上限を設けず左右40px以上、420px未満では16px以上の余白。420px以上では帯の位置を保つ。フォーカスの無い入力欄の上のホイールはページを動かす。入力欄を読むときは一度押す。Ctrl（Mac は ⌘）とホイール、ピンチは拡大縮小。表示切替・読み直し・絞り込み・明暗の変更ではページを動かさず、行き先を名指す操作か結果が画面外にできる操作だけ行き先を画面内に出す。")},
	{ID: "web.theme", Commands: []string{"serve"}, Statement: bilingual("Choose Light, Dark, or Follow OS at the top right. The preference stays in the same browser for the same host and port, across all four screens and projects. Different hostnames (including localhost versus 127.0.0.1), ports, and browsers do not share it. If browser storage cannot be read or written, the screens follow the OS and explain why. No hergy configuration file is changed.", "右上で明るい・暗い・OSに合わせるを選ぶ。同じブラウザの同じホストとポートで設定を保つ。ホスト・ポート・ブラウザが違えば共有しない。保存領域を読めない・書けないときはOSに合わせて{{reason}}を示す。hergy の設定ファイルは変えない。")},
	{ID: "documents.body", Commands: []string{"serve", "up"}, Statement: bilingual("roles/<role>.md and teams/<definition>/agreement.md hold complete Markdown text.\nSaved text is inserted unchanged into %{role_doc} and %{docs}; placeholders inside {{rule}}s are not expanded again.\nThe roster includes the short {{member-name}}, the first-line title, {{role-name}}, herdr contact and the self marker.\nArrows and {{role-name}}s in {{rule}}s are not interpreted. Only team.yaml turns: controls topology validation.\nThe {{team}} screen edits the {{team}} document and distinct shared {{role}}s side by side, with one full-text field per file, heading outlines and block counts. Saving a shared {{role}} updates that file for every reader; stale saves are refused by file hash.", "roles/<{{role-name}}>.md と teams/<{{team-definition-name}}>/agreement.md は Markdown の全文。保存した文をそのまま{{bootstrap-prompt}}へ入れ、{{rule}}内の置換は再展開しない。名簿は短い{{member-name}}、先頭行の題、{{role-name}}、herdr の連絡先、自分の印を含む。{{rule}}の矢印と{{role-name}}は解釈せず、team.yaml の turns: だけを検査する。{{team-agreement}}と共有{{role}}を横に並べ、各ファイルを全文の入力欄で編集する。共有{{role}}の保存は読む全員に及ぶ。古いファイルハッシュの保存は断る。")},
	{ID: "env.fixed", Commands: []string{"up", "hire", "apply", "refresh"}, Statement: bilingual("env is fixed when a pane is made. After editing env, run hergy down then hergy up.", "env はペインの作成時に決まる。変更したら hergy down のあと hergy up を使う。")},
	{ID: "prompt.missing-receipt", Commands: []string{"up", "refresh", "reprompt", "apply", "hire"}, Statement: bilingual("not received: %s (pane %s): %s\nretry: %s", "届いていません: %s（ペイン %s）: %s\n送り直す: %s"), Detail: true, ErrorKey: "launcher.undelivered", Slots: []TermID{"member", "place", "reason", "reprompt"}},
	{ID: "control.nudge-state", Commands: []string{"nudge"}, Statement: bilingual("%s: {{status}} %q; a nudge is sent only when the agent is idle or done. Run it again then", "%s はいま %q です。idle か done のときだけ送れます。idle か done になってから、もう一度実行してください"), Detail: true, ErrorKey: "error.nudge_busy", Slots: []TermID{"member", "status"}},
	{ID: "control.stop-self", Commands: []string{"stop"}, Statement: bilingual("%s runs in your own pane; a {{member}} cannot {{stop}} itself. Run it from another pane, or as the {{human}}", "%s はこのペインで動いています。自分自身は止められないので、別のペインから実行するか、{{human}}が実行してください"), Detail: true, ErrorKey: "error.stop_self", Slots: []TermID{"member"}},
	{ID: "refresh.no-team-pane", Commands: []string{"refresh", "apply"}, Statement: bilingual("%s: the team tab is absent or has no pane to split; run `hergy down` then `hergy up`", "%s を追加できるチームのペインが見つかりません。hergy down のあと hergy up し直してください"), Detail: true, ErrorKey: "error.refresh_no_pane", Slots: []TermID{"member"}},
	{ID: "start.cwd-directory", Commands: []string{"up", "hire"}, Statement: bilingual("cwd is not a directory: %s; pass a directory to -C", "cwd がディレクトリではありません: %s。-C にディレクトリを指定してください"), Detail: true, ErrorKey: "error.cwd_not_dir", Slots: []TermID{"place"}},
	{ID: "start.live-names", Commands: []string{"up", "hire"}, Statement: bilingual("live agent names already in use: %s; run `hergy down`, then run this again", "その名前のエージェントがすでに動いています: %s。hergy down で{{team}}を終了してから、もう一度実行してください"), Detail: true, ErrorKey: "error.live_names_in_use", Slots: []TermID{"herdr-name"}},
	{ID: "runtime.managed-pane", Commands: []string{"up", "down", "apply", "refresh", "reprompt", "hire"}, Statement: bilingual("run inside a Herdr-managed shell pane (HERDR_ENV=1 and HERDR_PANE_ID are required)", "herdr のペインの中で実行してください（HERDR_ENV=1 と HERDR_PANE_ID が必要です）"), Detail: true, ErrorKey: "error.not_under_herdr"},
	{ID: "web.prompt-preview", Commands: []string{"serve"}, Statement: bilingual("In the topology editor, selecting a {{member}} and opening プロンプト in the attribute panel shows the current topology text under Roster, Contact, Turn recipients, and Adding {{worker}}s (when present), without {{rule}} bodies. The “全文と差分を読む” button opens the recorded body, current text, and their full line diff. No text is folded. Opening the diff shows how many lines were added and removed, and 「最初の差へ」 moves to the first difference in one step; opening the diff does not scroll by itself. Text labels distinguish topology {{origin}}s from {{role}} and {{team}} {{rule}}s in current text and unchanged or added diff lines. Removed lines and the recorded body have no {{origin}} metadata and remain unmarked. The four topology sections are drawn as one band from the heading to the end of the section. A heading that comes from the template stands inside the band and carries no {{origin}} label. The recorded body shows the operation and time; it excludes the change-reason preamble added by {{apply}} or {{reprompt}} and is not a receipt. Current text includes unsaved topology edits. A stopped {{member}} or missing record shows the {{reason}} and current text only. The panel does not save or send prompts. The text is built with the name of a {{team}} running from this definition when one is running, and with the definition's name otherwise; the panel also says which name it used. When the running {{team}}'s name cannot be used, the text falls back to the definition's name and the {{reason}} is shown.After a {{start}}, a {{stop}}, or a change of aliases, the column's text and its {{rule-note}} match within the ten-second reading without pressing anything. A {{worker}}'s preview also includes unsaved edits and the running {{team}}'s name.", "トポロジーの編集画面で{{member}}を選び、属性パネルの「プロンプト」を開くと、今の定義から渡る文を「名簿」「連絡」「{{hands-the-turn-to}}相手」「{{worker}}の追加」（あるときだけ）に分けて、そのまま読めます。{{rule}}の本文はこの欄に出しません。「全文と差分を読む」ボタンで「渡した文」「今の文」「差」を切り替えます。本文は省略しません。「差」を開くと、追加と削除の行数が出て、「最初の差へ」で最初の差まで 1 回で移れます。開いたときに自動では送りません。「今の文」と差の変更なし・追加の行には、トポロジー{{origin}}か{{role}}・{{team-agreement}}かを文字の印で示します。削除行と記録の本文には{{origin}}の情報がないため、印を付けません。トポロジーの 4 節は、見出しから節の終わりまでを一続きの帯で示します。見出しがひな形の文字のときは、帯に入りますが、{{origin}}の印は付きません。「渡した文」は最後に記録された本文で、操作名と時刻を表示します。{{apply}}・{{reprompt}}の変更{{reason}}の前置きは含まず、受信の確認ではありません。「今の文」は未保存の編集も含みます。動いていない{{member}}や記録がない場合は、{{reason}}と今の文だけを表示します。このパネルでは保存や{{reprompt}}をしません。文は、その定義から動いている{{team}}があればその{{team}}の名前で、無ければ定義名で作ります。どちらの名前で作ったかも欄に出ます。実行中の{{team}}の名前で作れないときは、定義名で作り、{{reason}}を出します。{{start}}・終了・別名の増減のあとは、押さなくても 10 秒ごとの読みのうちに欄の文と注記が合います。{{worker}}のプレビューも、未保存の編集と動いている{{team}}の名前を含みます。")},
}
